import{Ht as e,Rt as t,ct as n,dt as r,gt as i,ht as a,mt as o,n as s}from"./chunks/framework.BkIgthgQ.js";var c=JSON.parse(`{"title":"管理员初始化","description":"在运行二进制的机器上用 kirivers admin add 创建第一个能登录管理台的账号。","frontmatter":{"title":"管理员初始化","description":"在运行二进制的机器上用 kirivers admin add 创建第一个能登录管理台的账号。"},"headers":[],"relativePath":"guide/config/bootstrap-admin.md","filePath":"guide/config/bootstrap-admin.md","lastUpdated":1790057721000}`),l={name:`guide/config/bootstrap-admin.md`};function u(s,c,l,u,d,f){let p=e(`ErrorCode`);return t(),r(`div`,null,[c[5]||=o(`<h1 id="管理员初始化" tabindex="-1">管理员初始化 <a class="header-anchor" href="#管理员初始化" aria-label="Permalink to “管理员初始化”">​</a></h1><p>服务已经能启动之后，在<strong>运行程序的那台电脑</strong>上创建第一个网页账号。这是命令行操作，不是网页注册。做完本页才能进入 <a href="/admin/quick-start">管理 → 快速上手</a>。</p><p><code>kirivers admin</code> 只读系统 YAML（PostgreSQL DSN），不读 <code>admin.yaml</code>。</p><h2 id="创建" tabindex="-1">创建 <a class="header-anchor" href="#创建" aria-label="Permalink to “创建”">​</a></h2><ol><li>打开终端，进入二进制与 YAML 所在目录（或传 <code>-config</code>）。</li><li>运行：</li></ol><div class="language-bash line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kirivers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> admin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alice</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="3"><li>按提示设置密码（或 <code>-password</code>）。成功：</li></ol><div class="language-text line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>created alice (&lt;uuid&gt;)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ol start="4"><li>浏览器打开管理平面（默认 <code>http://127.0.0.1:8081</code>），用该用户名登录。首次登录须绑定 TOTP（见 <a href="/admin/security">登录与两步验证</a>）。</li></ol><h2 id="其它动作" tabindex="-1">其它动作 <a class="header-anchor" href="#其它动作" aria-label="Permalink to “其它动作”">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th><th>成功输出</th></tr></thead><tbody><tr><td><code>kirivers admin list</code></td><td>列出实例管理员</td><td>表头 <code>USERNAME ID CREATED_AT</code></td></tr><tr><td><code>kirivers admin reset-password alice</code></td><td>重置密码</td><td><code>password reset for alice</code></td></tr><tr><td><code>kirivers admin clear-2fa alice</code></td><td>清除 TOTP / Passkey / 恢复码</td><td><code>cleared 2FA for alice</code></td></tr><tr><td><code>kirivers admin delete alice</code></td><td>删除账号</td><td><code>deleted alice</code></td></tr></tbody></table>`,11),n(`p`,null,[c[0]||=n(`code`,null,`clear-2fa`,-1),c[1]||=a(),c[2]||=n(`strong`,null,`不`,-1),c[3]||=a(`踢出现有会话。删除最后一名管理员失败（`,-1),i(p,{code:`LAST_ADMIN`}),c[4]||=a(`）。`,-1)])])}var d=s(l,[[`render`,u]]);export{c as __pageData,d as default};